<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { useFilters,useResource,refreshVersion } from '../composables/useDashboard';
import {number,time,duration,status,percent} from '../api/client';
import type {ReviewRequestsResponse,ReviewRequest} from '../../../contracts/review';
import type {WakesResponse,WakeItem} from '../../../contracts/contracts';
import RequestDetail from './review/RequestDetail.vue';
import WakeDetail from './review/WakeDetail.vue';
const props=defineProps<{kind:'requests'|'wakes'}>();
const route=useRoute(),router=useRouter(),{query}=useFilters();
const cursors=ref<string[]>([]);
const filters=computed(()=>query.value+'&'+new URLSearchParams({...(typeof route.query.q==='string'?{q:route.query.q}:{}),...(typeof route.query.outcome==='string'?{outcome:route.query.outcome}:{})}).toString());
watch([filters,refreshVersion],()=>cursors.value=[],{flush:'sync'});
const {data,loading,error,retry}=useResource<ReviewRequestsResponse|WakesResponse>(computed(()=>`${props.kind}?${filters.value}&limit=30${cursors.value.length?'&cursor='+encodeURIComponent(cursors.value.at(-1)!):''}`));
const items=computed(()=>(data.value?.items||[]) as (ReviewRequest&WakeItem)[]);
const id=(r:ReviewRequest&WakeItem)=>props.kind==='requests'?r.requestId:r.wakeId;
const selected=computed(()=>typeof route.query.selected==='string'?route.query.selected:'');
const detailGroup=computed(()=>String(route.query.detailGroup||route.query.group||items.value.find(r=>id(r)===selected.value)?.groupId||''));
const index=computed(()=>items.value.findIndex(r=>id(r)===selected.value&&r.groupId===detailGroup.value));
function choose(r:ReviewRequest&WakeItem){router.push({query:{...route.query,selected:id(r),detailGroup:r.groupId}});}
function close(){router.push({query:{...route.query,selected:undefined,detailGroup:undefined}});}
function key(e:KeyboardEvent){if(e.key==='Escape'&&selected.value)close();}
onMounted(()=>window.addEventListener('keydown',key));onUnmounted(()=>window.removeEventListener('keydown',key));
const short=(v:string)=>v.length>20?v.slice(0,12)+'…'+v.slice(-5):v;
const compact=(v:number|null|undefined)=>v==null?'—':v>=1000?`${(v/1000).toFixed(1).replace(/\.0$/,'')}k`:number(v);
const mobileTime=(value:number)=>{const date=new Date(value);return `${date.getMonth()+1}/${date.getDate()} ${[date.getHours(),date.getMinutes(),date.getSeconds()].map(part=>String(part).padStart(2,'0')).join(':')}`;};
const tokens=(r:ReviewRequest&WakeItem,format=number)=>[props.kind==='requests'?r.inputTokens:r.uncachedInputTokens,r.cachedInputTokens,r.outputTokens].map(format).join(' / ');
const detailWidth=ref(46);
function resize(e:PointerEvent){if(window.innerWidth<=700)return;const target=e.currentTarget as HTMLElement;target.setPointerCapture(e.pointerId);const move=(event:PointerEvent)=>{detailWidth.value=Math.max(30,Math.min(72,(window.innerWidth-event.clientX)/window.innerWidth*100));};const end=()=>{target.removeEventListener('pointermove',move);target.removeEventListener('pointerup',end);target.removeEventListener('pointercancel',end);};target.addEventListener('pointermove',move);target.addEventListener('pointerup',end);target.addEventListener('pointercancel',end);}
function resizeKey(e:KeyboardEvent){if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();detailWidth.value=Math.max(30,Math.min(72,detailWidth.value+(e.key==='ArrowLeft'?3:-3)));}}
</script>
<template><section class="review-list" :class="{'has-detail':selected}"><div class="list-pane"><div class="section-title"><h1>{{kind==='requests'?'模型请求':'唤醒'}}</h1><span class="muted">{{items.length}} 条 · 第 {{cursors.length+1}} 页</span></div><div v-if="error" role="alert" class="notice error">{{error}} <button @click="retry">重试</button></div><div v-else-if="loading" class="empty">加载中…</div><div v-else-if="!items.length" class="empty">此范围没有记录</div><div v-else class="table-wrap"><table class="compact-table" title="未记录或不可用显示 —，不能视为 0。"><thead><tr><th><span class="wide-label">时间 / 标识</span><span class="mobile-label">时间 / 用量</span></th><th class="secondary-column">群组</th><th>结果</th><template v-if="kind==='requests'"><th class="secondary-column">模型</th></template><template v-else><th class="secondary-column">请求</th><th class="secondary-column">工具</th></template><th class="token-column" title="未缓存输入 / 命中缓存 / 输出（含推理）">输入 / 缓存 / 输出</th><th class="cache-column" title="仅使用总输入与缓存计数有效配对的样本，按总输入 token 加权；未知不视为零"><span class="wide-label">缓存命中</span><span class="mobile-label">命中</span></th><th class="tps-column" title="成功且有输出用量请求的端到端输出速度，含等待，非解码速度"><span class="wide-label">模型 TPS ⓘ</span><span class="mobile-label">TPS</span></th><th class="duration-column"><span class="wide-label">{{kind==='wakes'?'整轮墙钟':'HTTP 耗时'}}</span><span class="mobile-label">耗时</span></th></tr></thead><tbody><tr v-for="r in items" :key="r.groupId+id(r)" :class="{selected:id(r)===selected&&r.groupId===detailGroup}" @click="choose(r)"><td><button class="row-link" @click.stop="choose(r)" :aria-label="'查看'+(kind==='requests'?'请求 ':'唤醒 ')+id(r)"><span class="wide-label">{{time(r.startedAt)}}</span><span class="mobile-label" :title="time(r.startedAt)">{{mobileTime(r.startedAt)}}</span></button><small class="mono record-id" :title="id(r)">{{short(id(r))}}</small><small class="mobile-label mobile-tokens" :title="`输入 / 缓存 / 输出：${tokens(r)}`">{{tokens(r,compact)}}</small></td><td class="secondary-column">{{r.groupId}}</td><td><span class="badge" :class="['error','timeout','failed'].includes(r.outcome||'')?'bad':''">{{kind==='wakes'&&r.finishedAt==null?'执行中':status(r.outcome)}}</span></td><template v-if="kind==='requests'"><td class="model-cell secondary-column" :title="r.model||''">{{r.model||'—'}}</td></template><template v-else><td class="secondary-column">{{number(r.modelRequests)}}</td><td class="secondary-column">{{number(r.toolCalls)}}</td></template><td class="token-column">{{tokens(r)}}</td><td class="cache-column" title="仅使用总输入与缓存计数有效配对的样本：缓存量之和 / 同批总输入之和；未知不视为零，总输入为零时比率未知。">{{percent(r.cacheHitRate)}}</td><td class="tps-column">{{r.performance?.modelTps!=null?r.performance.modelTps.toFixed(1):'—'}}</td><td class="duration-column">{{duration(r.durationMs)}}</td></tr></tbody></table></div><div class="pagination" title="每页最多30条"><span></span><div><button :disabled="loading||!cursors.length" @click="cursors.pop()">上一页</button><button :disabled="loading||!data?.nextCursor" @click="data?.nextCursor&&cursors.push(data.nextCursor)">下一页</button></div></div></div><div v-if="selected" class="resize-handle" role="separator" aria-label="调整详情宽度" aria-orientation="vertical" :aria-valuenow="Math.round(detailWidth)" aria-valuemin="30" aria-valuemax="72" tabindex="0" @pointerdown="resize" @keydown="resizeKey"></div><aside v-if="selected" class="detail-pane" :style="{'--detail-width':detailWidth+'%'}" aria-label="记录详情"><div class="detail-toolbar"><b>审阅详情</b><div><button :disabled="index<=0" @click="choose(items[index-1]!)">上一条</button><button :disabled="index<0||index>=items.length-1" @click="choose(items[index+1]!)">下一条</button><button aria-label="关闭详情" @click="close">关闭 ×</button></div></div><div class="detail-scroll"><RequestDetail v-if="kind==='requests'" :request-id="selected" :group-id="detailGroup"/><WakeDetail v-else :wake-id="selected" :group-id="detailGroup"/></div></aside></section></template>
